import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.IntStream;

public class Pb {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int tam = Integer.parseInt(br.readLine());
        String cad = br.readLine();

        List<String> arr = new ArrayList<>();
        final int[] cont = {0};
        final int[] mayor = {0};
        final boolean[] flg = {false};
        final StringBuilder word = new StringBuilder();

        IntStream.range(0, tam).forEachOrdered(i -> {
            char ch = cad.charAt(i);

            if (ch == '(') {
                if (cont[0] >= mayor[0]) {
                    mayor[0] = cont[0];
                }
                cont[0] = 0;
                flg[0] = true;
            } else if (ch == ')') {
                flg[0] = false;
                if (word.length() != 0) {
                    arr.add(word.toString());
                    word.setLength(0);
                }
            } else if (flg[0]) {
                if (ch != '_') {
                    word.append(ch);
                } else if (word.length() != 0) {
                    arr.add(word.toString());
                    word.setLength(0);
                }
            } else if (ch != '_') {
                cont[0]++;
                if (i == tam - 1 && cont[0] >= mayor[0]) {
                    mayor[0] = cont[0];
                }
            } else {
                if (cont[0] >= mayor[0]) {
                    mayor[0] = cont[0];
                }
                cont[0] = 0;
            }
        });

        System.out.println(mayor[0] + " " + arr.size());
    }
}
